#include <iostream>
#include <vector>
#include <string>

template<typename T>
bool areStrictlyIdentical(const std::vector<T>& v1, const std::vector<T>& v2) {
    if (v1.size() != v2.size()) return false;
    for (size_t i = 0; i < v1.size(); ++i) {
        if (v1[i] != v2[i]) return false;
    }
    return true;
}

template<typename T>
void addVector(std::vector<T>& dest, const std::vector<T>& src) {
    if (&dest == &src) { const auto copy = src; addVector(dest, copy); return; }
    dest.reserve(dest.size() + src.size());
    dest.insert(dest.end(), src.begin(), src.end());
}

int main() {
    std::vector<int> a = {1, 3, 5};
    std::vector<int> b = {1, 3, 5};
    std::vector<int> c = {7, 9};

    std::cout << std::boolalpha;
    std::cout << "Identical: " << areStrictlyIdentical(a, b) << "\n";

    addVector(a, c);
    std::cout << "After append size: " << a.size() << "\n";
    for (size_t i = 0; i < a.size(); ++i) {
        std::cout << a[i] << (i + 1 == a.size() ? "" : " ");
    }
    std::cout << "\n";
    return 0;
}

