int main() {
    // Input corresponding to textbook sample run: a = [1 2 1 2 3 1 4 5 3], b = [2 5 3]
    double a11 = 1, a12 = 2, a13 = 1;
    double a21 = 2, a22 = 3, a23 = 1;
    double a31 = 4, a32 = 5, a33 = 3;
    double b1 = 2, b2 = 5, b3 = 3;

    double detA = a11 * a22 * a33 + a31 * a12 * a23 + a13 * a21 * a32
                - a13 * a22 * a31 - a11 * a23 * a32 - a33 * a21 * a12;

    if (std::abs(detA) < 1e-9) {
        std::cout << "The equation has no solution.\n";
    } else {
        double x = ((a22 * a33 - a23 * a32) * b1 + (a13 * a32 - a12 * a33) * b2 + (a12 * a23 - a13 * a22) * b3) / detA;
        double y = ((a23 * a31 - a21 * a33) * b1 + (a11 * a33 - a13 * a31) * b2 + (a13 * a21 - a11 * a23) * b3) / detA;
        double z = ((a21 * a32 - a22 * a31) * b1 + (a12 * a31 - a11 * a32) * b2 + (a11 * a22 - a12 * a21) * b3) / detA;
        std::cout << "The solution is " << static_cast<int>(std::round(x)) << " "
                  << static_cast<int>(std::round(y)) << " "
                  << static_cast<int>(std::round(z)) << "\n";
    }
    return 0;
}
